/**
 * The router factory (ADR-015). It composes, once, the configured layouts with the
 * project's routes, the public routes, the built-in system pages and the page extras,
 * installs the guards, and throws when a menu item, a placeholder or a routing contract
 * names a route the composition does not contain, when a menu item names an action the
 * project did not pass, or when two routes share a name.
 * Generated by forge: it imports no project code; the project passes its contributions.
 */
import { defineComponent, h, type Component } from 'vue'
import { createRouter, createWebHistory, type RouteRecordRaw, type Router } from 'vue-router'
import HeaderSidebarShell from '@/shared/layouts/HeaderSidebarShell.vue'
import { application } from './config'
import { setApplicationContext } from './context'
import type { ApplicationConfig, ApplicationOptions, MenuItemConfig, RoutingKey } from './contracts'
import { installGuards } from './guards'
import { extraPages, systemPages } from './pages'

const SHELLS: Record<string, Component> = { 'header-sidebar': HeaderSidebarShell }

const SYSTEM_PATHS: Record<Exclude<RoutingKey, 'landing'>, string> = {
  sign_in: '/login',
  auth_stuck: '/auth/stuck',
  forbidden: '/forbidden',
  not_found: '/:pathMatch(.*)*',
}
const SYSTEM_TITLES: Record<Exclude<RoutingKey, 'landing'>, string> = {
  sign_in: 'Sign in',
  auth_stuck: 'Sign-in delayed',
  forbidden: 'No access',
  not_found: 'Page not found',
}
const EXTRA_ROUTES: Record<string, { path: string, title: string }> = {
  // Off `/`, which always opens the landing route.
  home: { path: 'home', title: 'Home' },
  profile: { path: 'profile', title: 'Profile' },
  settings: { path: 'settings', title: 'Settings' },
}

function shell(layout: string, name: string): Component {
  const component = SHELLS[name]
  if (!component) throw new Error(`Layout '${layout}' uses shell '${name}', which this app does not have.`)
  return defineComponent({ name: 'ApplicationShell', setup: () => () => h(component, { layout }) })
}

function routeNames(records: RouteRecordRaw[], names: string[] = []): string[] {
  for (const record of records) {
    if (typeof record.name === 'string') names.push(record.name)
    if (record.children) routeNames(record.children, names)
  }
  return names
}

/** The records from the top down to the one named `name`, searching the children too. */
function findChain(records: RouteRecordRaw[], name: string): RouteRecordRaw[] | null {
  for (const record of records) {
    if (record.name === name) return [record]
    const found = record.children ? findChain(record.children, name) : null
    if (found) return [record, ...found]
  }
  return null
}

/**
 * A record's view, meta and props at `path`, without its name or other children; the
 * route the copy ends on keeps its redirect, which is all a redirecting route has.
 */
function copyView(record: RouteRecordRaw, path: string, child?: RouteRecordRaw): RouteRecordRaw {
  return {
    path,
    meta: { ...record.meta },
    ...('component' in record && record.component ? { component: record.component } : {}),
    ...('components' in record && record.components ? { components: record.components } : {}),
    ...('props' in record && record.props !== undefined ? { props: record.props } : {}),
    ...(child ? { children: [child] } : 'redirect' in record && record.redirect ? { redirect: record.redirect } : {}),
  } as RouteRecordRaw
}

/**
 * A project route named as routing.not_found answers every unknown address too: one
 * application-wide catch-all renders it inside the layout and the parents it sits in,
 * and keeps the address (a not-found route that redirects goes where it redirects).
 */
function addNotFoundCatchAll(records: RouteRecordRaw[], name: string): void {
  const chain = findChain(records, name)
  if (!chain || (chain.length === 1 && chain[0]!.path.includes(':pathMatch'))) return
  const catchAll = chain.reduceRight<RouteRecordRaw | undefined>(
    (child, record, index) => copyView(record, index === 0 ? '/:pathMatch(.*)*' : '', child),
    undefined,
  )
  records.push(catchAll!)
}

function menuTargets(items: MenuItemConfig[]): string[] {
  return items.flatMap(item => [...(item.to ? [item.to] : []), ...menuTargets(item.children ?? [])])
}

function menuActions(items: MenuItemConfig[]): string[] {
  return items.flatMap(item => [...(item.action ? [item.action] : []), ...menuActions(item.children ?? [])])
}

function check(router: Router, config: ApplicationConfig, layouts: string[], actions: Record<string, unknown>): void {
  const missing = (name: string) => !router.hasRoute(name)
  const first = layouts[0]!
  for (const [key, name] of Object.entries(config.routing)) {
    // The layout mounted at `/` may start on a landing route of its own, checked with the layout.
    if (key === 'landing' && config.layouts[first]!.landing) continue
    if (name && missing(name)) {
      const hint = key === 'landing' && layouts.length < Object.keys(config.layouts).length
        ? `; a layout mounted without it at '/' names a landing route of its own (layouts.${first}.landing)`
        : ''
      throw new Error(`routing.${key} names route '${name}', which no route has${hint}.`)
    }
  }
  for (const layout of layouts) {
    const { menus, placeholder, landing } = config.layouts[layout]!
    if (placeholder && missing(placeholder)) {
      throw new Error(`layouts.${layout}.placeholder names route '${placeholder}', which no route has.`)
    }
    if (landing && missing(landing)) {
      throw new Error(`layouts.${layout}.landing names route '${landing}', which no route has.`)
    }
    for (const [menu, sections] of Object.entries(menus)) {
      const items = sections.flatMap(section => section.items)
      for (const target of menuTargets(items)) {
        if (missing(target)) throw new Error(`A ${menu} menu item of layout '${layout}' opens route '${target}', which no route has.`)
      }
      for (const action of menuActions(items)) {
        if (!actions[action]) throw new Error(`A ${menu} menu item of layout '${layout}' runs action '${action}', which was not passed in actions.`)
      }
    }
  }
}

export function createApplicationRouter(options: ApplicationOptions, config: ApplicationConfig = application): Router {
  const layouts = options.activeLayouts ?? Object.keys(config.layouts)
  const unknown = layouts.filter(layout => !config.layouts[layout])
  if (unknown.length) throw new Error(`Unknown layouts ${unknown.join(', ')}; the configuration has ${Object.keys(config.layouts).join(', ')}.`)
  // The layout mounted at `/` decides where `/` goes: its own landing route, or the configuration's.
  const ownLanding = config.layouts[layouts[0]!]?.landing
  const routing = ownLanding ? { ...config.routing, landing: ownLanding } : config.routing

  const records: RouteRecordRaw[] = layouts.map((layout, index) => {
    const children: RouteRecordRaw[] = [...(options.routes?.[layout] ?? [])]
    if (index === 0) {
      for (const extra of config.extras) {
        const page = extraPages[extra]
        const route = EXTRA_ROUTES[extra]
        // No meta.menu: the item whose `to` opens the page is the active one, whatever its id.
        if (page && route) children.push({ path: route.path, name: extra, component: page, meta: { title: route.title } })
      }
    }
    // `/` opens the landing route, and `/<layout>` a further layout's own, unless a page already sits there.
    const start = index === 0 ? routing.landing : config.layouts[layout]!.landing
    if (start && !children.some(child => child.path === '')) {
      children.push({ path: '', redirect: { name: start } })
    }
    return {
      path: index === 0 ? '/' : `/${layout}`,
      component: options.layouts?.[layout] ?? shell(layout, config.layouts[layout]!.shell),
      meta: { requiresAuth: config.auth, layout },
      children,
    } as RouteRecordRaw
  })
  for (const route of options.publicRoutes ?? []) {
    records.push({ ...route, meta: { requiresAuth: false, ...route.meta } } as RouteRecordRaw)
  }
  for (const key of config.builtin) {
    if (key === 'landing') continue
    const page = systemPages[key]
    const name = config.routing[key]
    if (page && name) records.push({ path: SYSTEM_PATHS[key], name, component: page, meta: { requiresAuth: false, title: SYSTEM_TITLES[key] } })
  }

  if (config.routing.not_found && !config.builtin.includes('not_found')) {
    addNotFoundCatchAll(records, config.routing.not_found)
  }

  const names = routeNames(records)
  const duplicates = [...new Set(names.filter((name, i) => names.indexOf(name) !== i))]
  if (duplicates.length) throw new Error(`Route names used twice: ${duplicates.join(', ')}.`)

  const router = createRouter({ history: options.history ?? createWebHistory(), routes: records })
  check(router, config, layouts, options.actions ?? {})
  setApplicationContext({ auth: options.auth, actions: options.actions ?? {}, routing })
  installGuards(router, { auth: options.auth, routing, enabled: config.auth })
  return router
}
